int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port, struct br_ip *group) {
    int err = -EINVAL;

    spin_lock(&br->multicast_lock);

    if (!netif_running(br->dev))
        goto out;

    if (port && !port->enabled)
        goto out;

    struct br_multicast *mc;

    if (!port) {
        mc = br_multicast_alloc(group);
        if (!mc)
            goto out;

        list_add(&mc->list, &br->multicast_list);
    } else {
        struct br_multicast_port_group *pg;

        pg = kmalloc(sizeof(*pg), GFP_KERNEL);
        if (!pg)
            goto out;

        pg->group = *group;
        pg->port = port;
        pg->timer.function = br_multicast_timer;
        pg->timer.data = (unsigned long)pg;

        list_add(&pg->list, &port->multicast_list);
        add_timer(&pg->timer);
        err = 0;
    }

    err = 0;

out:
    spin_unlock(&br->multicast_lock);
    return err;
}

int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port,
                           struct br_ip *group)
{
    int err = -EINVAL;

    write_lock(&br->multicast_lock);

    if (!netif_running(br->dev))
        goto out;

    if (port && !port->enabled) {
        err = -EOPNOTSUPP;
        goto out;
    }

    if (!port) {
        struct net_bridge_mcast *mc;

        mc = kzalloc(sizeof(*mc), GFP_KERNEL);
        if (!mc)
            goto out;

        br_ip_copy(&mc->addr, group);
        hlist_add_head(&mc->hlist, &br->multicast);
    } else {
        struct net_bridge_port_group *pgrp;

        pgrp = kzalloc(sizeof(*pgrp), GFP_KERNEL);
        if (!pgrp)
            goto out;

        pgrp->port = port;
        br_ip_copy(&pgrp->addr, group);
        hlist_add_head(&pgrp->hlist, &port->mglist);

        pgrp->timer.expires = jiffies + BR_MULTICAST_TIMER_MS * HZ / 1000;
        add_timer(&pgrp->timer);
    }

    err = 0;

out:
    write_unlock(&br->multicast_lock);
    return err;
}

int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port,
                           struct br_ip *group)
{
    int err = 0;

    spin_lock(&br->multicast_lock);
    if (br->flags & BR_FLAG_RUNNING) {
        struct net_bridge_mc *mc;

        mc = kmalloc(sizeof(*mc), GFP_ATOMIC);
        if (!mc) {
            err = -ENOMEM;
            goto out;
        }

        if (port) {
            struct net_bridge_port_mc *port_mc;

            port_mc = kmalloc(sizeof(*port_mc), GFP_ATOMIC);
            if (!port_mc) {
                kfree(mc);
                err = -ENOMEM;
                goto out;
            }

            port_mc->group = *group;
            port_mc->port = port;
            hlist_add_head(&port_mc->list, &port->mc_list);

            mc->port_group = port_mc;
        } else {
            mc->group = *group;
            hlist_add_head(&mc->list, &br->multicast_list);
        }

        mc->timer.expires = jiffies + BR_MULTICAST_TIMER_INTERVAL;
        add_timer(&mc->timer);
    } else {
        err = -EINVAL;
    }

out:
    spin_unlock(&br->multicast_lock);
    return err;
}

int br_add_multicast_group(struct net_bridge *br, struct net_bridge_port *port, struct br_ip *group) {
    int ret = 0;

    spin_lock(&br->multicast_lock);

    if (!netif_running(br->dev)) {
        ret = -EINVAL;
        goto out;
    }

    if (port && !port->enabled) {
        ret = -EINVAL;
        goto out;
    }

    struct br_multicast *mc = kmalloc(sizeof(*mc), GFP_KERNEL);
    if (!mc) {
        ret = -ENOMEM;
        goto out;
    }

    memcpy(&mc->group, group, sizeof(*group));

    if (!port) {
        list_add(&mc->list, &br->multicast_list);
    } else {
        struct br_multicast_port_group *mc_port_group = kmalloc(sizeof(*mc_port_group), GFP_KERNEL);
        if (!mc_port_group) {
            kfree(mc);
            ret = -ENOMEM;
            goto out;
        }

        mc_port_group->group = *group;
        mc_port_group->port = port;
        list_add(&mc_port_group->list, &port->multicast_list);

        setup_timer(&mc_port_group->timer_membership, handle_membership_timer, (unsigned long)mc_port_group);
        setup_timer(&mc_port_group->timer_query, handle_query_timer, (unsigned long)mc_port_group);
    }

out:
    spin_unlock(&br->multicast_lock);
    return ret;
}

int br_add multicast_group(struct net_bridge *br, struct net_bridge_port *port, struct br_ip *group) {
    int result = -1;

    spin_lock(&br->multicast_lock);

    if (!netif_running(br->dev)) {
        spin_unlock(&br->multicast_lock);
        return -EINVAL;
    }

    if (port && !port->enabled) {
        spin_unlock(&br->multicast_lock);
        return -EINVAL;
    }

    struct br_multicast_entry *mcast_entry = kmalloc(sizeof(struct br_multicast_entry), GFP_KERNEL);
    if (!mcast_entry) {
        spin_unlock(&br->multicast_lock);
        return -ENOMEM;
    }

    memcpy(&mcast_entry->group, group, sizeof(struct br_ip));

    if (!port) {
        list_add(&mcast_entry->list, &br->multicast_list);
    } else {
        struct br_multicast_port_group *port_group = kmalloc(sizeof(struct br_multicast_port_group), GFP_KERNEL);
        if (!port_group) {
            kfree(mcast_entry);
            spin_unlock(&br->multicast_lock);
            return -ENOMEM;
        }

        port_group->port = port;
        memcpy(&port_group->group, group, sizeof(struct br_ip));

        list_add(&port_group->list, &port->multicast_list);
        mcast_entry->port_group = port_group;
    }

    mcast_entry->timer = jiffies + mcast_entry->timeout;
    mcast_entry->query_timer = jiffies + BR_MULTICAST_QUERY_TIMEOUT;

    spin_unlock(&br->multicast_lock);

    result = 0;
    return result;
}
